interface StackMarqueeProps {
  onOpenFullStack?: () => void;
}

export const StackMarquee: React.FC<StackMarqueeProps> = () => {
  const { ref, isInView } = useInView<HTMLElement>({ threshold: 0.1 });

  return (
    <section ref={ref} id="stack" className="py-12 space-y-8">
      {/* =========================================================================
          Section Header with Walking Torch Platform Anchor (CRITICAL)
          ========================================================================= */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3.5 flex-1">
          <h2 className="text-2xl sm:text-3xl font-bold font-display tracking-tight text-text-primary whitespace-nowrap">
            <LetterReveal text="Tech Stack" isActive={isInView} baseDelay={60} staggerMs={24} />
          </h2>
          {/* Walking Torch Platform Anchor - DO NOT REMOVE */}
          <div
            id="stack-ledge-platform"
            className={`h-[1.5px] flex-1 bg-border-main relative min-w-[30px] sm:min-w-[60px] ${isInView ? 'animate-divider-expand' : ''}`}
            style={{ animationDelay: '120ms' }}
          />
        </div>
      </div>

      {/* =========================================================================
          3-Line Slow Moving Flow Stack (Open Borderless Stream, Larger Tech Pills)
          ========================================================================= */}
      <div
        className={`relative flex flex-col items-center justify-center overflow-hidden py-4 sm:py-6 space-y-4 sm:space-y-5 ${
          isInView ? 'animate-hero-fade-up' : 'opacity-0 translate-y-6'
        }`}
        style={{ animationDelay: '200ms' }}
      >
        {/* Line 1 - Left to Right (Frontend & Mobile) - Calm 76s */}
        <div className="group flex overflow-hidden py-1 w-full select-none">
          <div
            className="flex shrink-0 gap-3.5 sm:gap-4.5 animate-marquee group-hover:[animation-play-state:paused]"
            style={{ animationDuration: '76s' }}
          >
            {[...FLOW_ROW_1, ...FLOW_ROW_1, ...FLOW_ROW_1, ...FLOW_ROW_1].map((tech, idx) => {
              const TechIcon = TECH_ICONS[tech] || Layers;
              return (
                <div
                  key={idx}
                  className="inline-flex items-center gap-3 rounded-full border border-border-main bg-panel-bg px-5 py-2.5 sm:px-6 sm:py-3 text-sm sm:text-base font-display font-medium text-text-secondary hover:text-text-primary hover:border-emerald-500/60 hover:bg-panel-hover hover:scale-105 hover:-translate-y-1 transition-all duration-200 cursor-pointer shadow-xs shrink-0 select-none"
                >
                  <TechIcon className="w-5 h-5 sm:w-6 sm:h-6 shrink-0" />
                  <span className="font-display font-medium text-text-primary">{tech}</span>
                </div>
              );
            })}
          </div>
        </div>

        {/* Line 2 - Right to Left (Backend & Cloud) - Calm 84s */}
        <div className="group flex overflow-hidden py-1 w-full select-none">
          <div
            className="flex shrink-0 gap-3.5 sm:gap-4.5 animate-marquee-reverse group-hover:[animation-play-state:paused]"
            style={{ animationDuration: '84s' }}
          >
            {[...FLOW_ROW_2, ...FLOW_ROW_2, ...FLOW_ROW_2, ...FLOW_ROW_2].map((tech, idx) => {
              const TechIcon = TECH_ICONS[tech] || Layers;
              return (
                <div
                  key={idx}
                  className="inline-flex items-center gap-3 rounded-full border border-border-main bg-panel-bg px-5 py-2.5 sm:px-6 sm:py-3 text-sm sm:text-base font-display font-medium text-text-secondary hover:text-text-primary hover:border-emerald-500/60 hover:bg-panel-hover hover:scale-105 hover:-translate-y-1 transition-all duration-200 cursor-pointer shadow-xs shrink-0 select-none"
                >
                  <TechIcon className="w-5 h-5 sm:w-6 sm:h-6 shrink-0" />
                  <span className="font-display font-medium text-text-primary">{tech}</span>
                </div>
              );
            })}
          </div>
        </div>

        {/* Line 3 - Left to Right (Databases, AI & Systems) - Calm 72s */}
        <div className="group flex overflow-hidden py-1 w-full select-none">
          <div
            className="flex shrink-0 gap-3.5 sm:gap-4.5 animate-marquee group-hover:[animation-play-state:paused]"
            style={{ animationDuration: '72s' }}
          >
            {[...FLOW_ROW_3, ...FLOW_ROW_3, ...FLOW_ROW_3, ...FLOW_ROW_3].map((tech, idx) => {
              const TechIcon = TECH_ICONS[tech] || Layers;
              return (
                <div
                  key={idx}
                  className="inline-flex items-center gap-3 rounded-full border border-border-main bg-panel-bg px-5 py-2.5 sm:px-6 sm:py-3 text-sm sm:text-base font-display font-medium text-text-secondary hover:text-text-primary hover:border-emerald-500/60 hover:bg-panel-hover hover:scale-105 hover:-translate-y-1 transition-all duration-200 cursor-pointer shadow-xs shrink-0 select-none"
                >
                  <TechIcon className="w-5 h-5 sm:w-6 sm:h-6 shrink-0" />
                  <span className="font-display font-medium text-text-primary">{tech}</span>
                </div>
              );
            })}
          </div>
        </div>

        {/* Deep Gradient Fades at Left & Right Edges Blending into Page Background */}
        <div className="pointer-events-none absolute inset-y-0 left-0 w-20 sm:w-36 bg-gradient-to-r from-bg-main via-bg-main/90 to-transparent z-10" />
        <div className="pointer-events-none absolute inset-y-0 right-0 w-20 sm:w-36 bg-gradient-to-l from-bg-main via-bg-main/90 to-transparent z-10" />
      </div>
    </section>
  );
};

